output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Carts are prohibited in single-file shelf canyons, i.e. aisles only one cell wide with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfCanyon"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_single_file",
    "text": "A shopper may not move a cart into a single-file shelf canyon.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfCanyon"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "park_at_pedestrian_mouth",
    "text": "When a shopper reaches the mouth of a pedestrian-only shelf aisle with a cart, they are obliged to park the cart there.",
    "abstraction": {
      "state_properties": {
        "pedestrianAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartAtPedestrianAisleMouth": {
          "and": [
            "hasCart",
            "pedestrianAisleMouth"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "pedestrianAisleMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartAtPedestrianAisleMouth",
      "discharge": "parkCartAtMouth"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart, the shopper must retrieve a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {
        "wideOpenArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "wideOpenArea"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "main_shelf_needs_cart",
    "text": "Shelf interactions on the main lower shelf face must be performed while holding the cart.",
    "abstraction": {
      "state_properties": {
        "mainLowerShelfFace": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "mainLowerShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "side_bay_needs_cart",
    "text": "Shelf interactions in two-cell-wide side bays must be performed with the cart, unlike single-file pedestrian aisles.",
    "abstraction": {
      "state_properties": {
        "twoWideSideShelfBay": {
          "and": [
            "adjShelf",
            {
              "eq": [
                "freeWidthH",
                2
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "twoWideSideShelfBay",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_wide_open",
    "text": "Carts may only be parked in wide open non-shelf areas, not in narrow passages or beside shelves.",
    "abstraction": {
      "state_properties": {
        "wideOpenParkingArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideOpenParkingArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_aisles_one_way_east",
    "text": "Cart traffic in public cart-accessible aisles is one-way: shoppers pushing carts must not move west.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfCanyon": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessiblePublicAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                2
              ]
            },
            {
              "not": "singleFileShelfCanyon"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "hasCart",
          "cartAccessiblePublicAisle"
        ]
      }
    }
  }
]
